/**
 * @fileoverview The Studio's Starters gallery: each starter's picture, its
 * params as a schema for `lcards-astro-schema-form`, and what it adds; the
 * pictures of the add-object gallery and the shape picker.
 *
 * Pictures are generated by `scripts/astro-pictures.mjs` into
 * `src/assets/images/astro-studio/` (copied to custom_components/lcards/images/
 * by the build, served at /lcards/images/),
 * never bundled.
 */

import { applyStarter, starterParams } from '../../../core/astrometrics/starters/index.js';
import { bundleUrl } from '../../../utils/bundle-url.js';

/** Where the Studio's generated pictures are served */
export const PICTURE_BASE = '/lcards/images/astro-studio/';

/**
 * A starter's picture URL.
 * @param {string} id
 */
export function starterPicture(id) {
  return bundleUrl(`${PICTURE_BASE}starter-${id}.webp`);
}

/**
 * An object type's picture URL (the add-object gallery).
 * @param {string} type
 */
export function typePicture(type) {
  return bundleUrl(`${PICTURE_BASE}type-${type}.webp`);
}

/**
 * A shape's picture URL (the shape picker of grids, volumes and images).
 * @param {string} type
 * @param {string} shape
 */
export function shapePicture(type, shape) {
  return bundleUrl(`${PICTURE_BASE}shape-${type}-${shape}.webp`);
}

/**
 * The add-object gallery's groups, in order: what an object is for, and the
 * types in each (every type in one; Studio only, so not in the main chunk).
 */
export const TYPE_GROUPS = /** @type {const} */ ([
  { id: 'maps', header: 'Maps and grids', icon: 'mdi:grid', types: ['grid', 'volume', 'image'] },
  { id: 'bodies', header: 'Bodies', icon: 'mdi:earth', types: ['sphere', 'belt', 'asteroid', 'comet'] },
  { id: 'routes', header: 'Routes and motion', icon: 'mdi:vector-polyline', types: ['ring', 'path', 'beam', 'trail'] },
  { id: 'light', header: 'Light and clouds', icon: 'mdi:white-balance-sunny', types: ['glow', 'nebula', 'galaxy', 'lightning'] },
  { id: 'models', header: 'Ships and models', icon: 'mdi:rocket', types: ['model', 'cube', 'crystalline'] },
  { id: 'systems', header: 'Systems', icon: 'mdi:folder-outline', types: ['system'] }
]);

/** A point id or [x, y, z]: the schema shape the form shows as a point picker */
const POINT_SCHEMA = { oneOf: [{ type: 'string' }, { type: 'array', items: { type: 'number' }, minItems: 3, maxItems: 3 }] };

/**
 * A starter's params as form properties, by key.
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 * @returns {Record<string, any>}
 */
export function starterParamSchema(starter) {
  /** @type {Record<string, any>} */
  const out = {};
  for (const p of starter.params) {
    const hints = { 'x-ui-hints': { label: p.label } };
    // a size: its units beside the field (the form reads "scene units"), real where they are named, fitted where not
    const sizeNote = p.real !== undefined
      ? `In scene units; in named units (km, au, ly) it starts at a real size${p.fit ? ', in a scene without named units at a size that fits it' : ''}.`
      : p.fit ? 'In scene units; it starts at a size that fits the scene.' : undefined;
    const description = [p.helper, sizeNote].filter(Boolean).join(' ') || undefined;
    if (p.type === 'number') out[p.key] = { type: 'number', description, ...hints };
    else if (p.type === 'point') out[p.key] = { ...POINT_SCHEMA, description, ...hints };
    // a fixed list: a dropdown with each option's name (a list that takes other values too is a text field with choices)
    else if (p.options?.length && !p.custom) {
      out[p.key] = {
        type: 'string', enum: p.options.map((o) => o.value), default: p.default, description, ...hints,
        enumDescriptions: Object.fromEntries(p.options.map((o) => [o.value, o.label]))
      };
    } else out[p.key] = { type: 'string', description, ...hints };
  }
  return out;
}

/**
 * Dropdown words for params that take a list or anything typed (the form's `choices`).
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 * @returns {Record<string, string[]>}
 */
export function starterParamChoices(starter) {
  return Object.fromEntries(starter.params.filter((p) => p.options?.length && p.custom).map((p) => [p.key, (p.options ?? []).map((o) => o.value)]));
}

/**
 * The params to show: each default (a real size in the target's named
 * `units`, or sized to fit the `target` when they have no name), then what
 * was typed over it.
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 * @param {Record<string, any>} [typed]
 * @param {string | null} [units]
 * @param {Record<string, any> | null} [target] - the lists it goes into: the card config, or a system
 */
export function starterParamValues(starter, typed = {}, units = null, target = null) {
  const filled = starterParams(starter, typed, units, target);
  return { ...Object.fromEntries(starter.params.map((p) => [p.key, p.real !== undefined || p.fit ? filled[p.key] : p.default])), ...typed };
}

/**
 * What a fragment holds, in words ("12 points, 6 objects, 3 views"), or ''.
 * @param {import('../../../core/astrometrics/starters/index.js').StarterFragment} frag
 */
export function fragmentCounts(frag) {
  const n = (/** @type {number} */ c, /** @type {string} */ word) => (c ? `${c} ${word}${c === 1 ? '' : 's'}` : null);
  return [
    n(frag.points?.length ?? 0, 'point'),
    n(frag.objects?.length ?? 0, 'object'),
    n(Object.keys(frag.views ?? {}).length, 'view')
  ].filter(Boolean).join(', ');
}

/**
 * What a starter adds with these params, in words, or its error.
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 * @param {Record<string, any>} [typed]
 */
export function starterAdds(starter, typed = {}) {
  const out = applyStarter({}, starter, typed);
  return out.added ? fragmentCounts(out.added) : String(out.error);
}

/** Unit names in words */
const UNIT_WORDS = /** @type {Record<string, string>} */ ({ m: 'metres', km: 'kilometres', au: 'astronomical units', ly: 'light years', pc: 'parsecs' });

/**
 * What units a scene starter is in, in words (its detail says so).
 * @param {import('../../../core/astrometrics/starters/index.js').Starter} starter
 */
export function sceneUnitsText(starter) {
  const units = starter.build(starterParams(starter), { units: null }).units;
  return units
    ? `In ${UNIT_WORDS[units] ?? units}: sizes and distances are real, and parts you add start at their real size.`
    : 'In scene units, sized to be seen: parts you add are sized to fit it.';
}
